Theorem corrected_row_sum (s : State) (i : Inputs) :
  word 130 (BoothPadding.BoothPadding.correctedSum (actualRows s i)) =
  word 130 (SignedWords.signed 65 (nio_5Fa i) * SignedWords.signed 65 (nio_5Fb i)).
Proof.
  unfold actualRows; rewrite <- (raw_model_0 s i).
  rewrite suffix_0, digits_product, window_sum_signed; apply f_equal; ring.
Qed.
Theorem two_edges (s : State) (first second after : Inputs)
  (capture : word 1 (nio_5FregEnables_5F0 first) = 1)
  (transfer : word 1 (nio_5FregEnables_5F1 second) = 1) :
  nio_5Fresult (observe (step (step s first) second) after) =
    word 130 (SignedWords.signed 65 (nio_5Fa first) * SignedWords.signed 65 (nio_5Fb first)).
Proof. rewrite (corrected_rows_after_two_edges s first second after capture transfer); apply corrected_row_sum. Qed.
Print Assumptions corrected_row_sum.
Print Assumptions two_edges.
End ArrayRowSum.
